import { useId, useState } from "react";
import { Badge } from "@/registry/erbium/ui/badge";
import { Checkbox } from "@/registry/erbium/ui/checkbox";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemSeparator,
  ItemTitle,
} from "@/registry/erbium/ui/item";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

const books = [
  {
    author: "Ursula K. Le Guin",
    badgeVariant: "info",
    cover: "bg-info text-info-foreground",
    id: "left-hand-of-darkness",
    monogram: "LH",
    status: "Reading",
    title: "The Left Hand of Darkness",
    year: 1969,
  },
  {
    author: "Virginia Woolf",
    badgeVariant: "success",
    cover: "bg-warning text-warning-foreground",
    id: "a-room-of-ones-own",
    monogram: "AR",
    status: "Finished",
    title: "A Room of One’s Own",
    year: 1929,
  },
  {
    author: "Ursula K. Le Guin",
    badgeVariant: "secondary",
    cover: "bg-error text-error-foreground",
    id: "the-dispossessed",
    monogram: "TD",
    status: "To read",
    title: "The Dispossessed",
    year: 1974,
  },
  {
    author: "Robin Wall Kimmerer",
    badgeVariant: "secondary",
    cover: "bg-success text-success-foreground",
    id: "braiding-sweetgrass",
    monogram: "BS",
    status: "To read",
    title: "Braiding Sweetgrass",
    year: 2013,
  },
] as const;

const ItemBookLibrary = () => {
  const [selected, setSelected] = useState<string[]>([books[0].id, books[1].id]);
  const idPrefix = useId();
  const allSelected = selected.length === books.length;
  const someSelected = selected.length > 0 && !allSelected;

  return (
    <section className="w-[min(42rem,90vw)] space-y-4" aria-label="Book library">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="text-subtitle">My library</h2>
          <p className="text-caption text-muted-foreground">Books on your shelf</p>
        </div>
        <p className="text-caption text-muted-foreground" role="status">
          {selected.length} of {books.length} selected
        </p>
      </div>

      <Field orientation="horizontal" className="px-4">
        <Checkbox
          id={`${idPrefix}-all`}
          checked={allSelected}
          indeterminate={someSelected}
          onCheckedChange={(checked) => {
            setSelected(checked ? books.map((book) => book.id) : []);
          }}
        />
        <FieldLabel htmlFor={`${idPrefix}-all`}>Select all books</FieldLabel>
      </Field>

      <ItemGroup variant="panel">
        {books.map((book, index) => {
          const checked = selected.includes(book.id);
          const checkboxId = `${idPrefix}-${book.id}`;

          return (
            <Item
              render={<Field orientation="horizontal" />}
              key={book.id}
              role="listitem"
              data-selected={checked}
              className="relative"
            >
              {index > 0 && (
                <ItemSeparator className="absolute inset-x-4 top-0 mx-0! my-0! w-auto" />
              )}
              <Checkbox
                id={checkboxId}
                checked={checked}
                aria-label={`Select ${book.title}`}
                onCheckedChange={(nextChecked) => {
                  setSelected((current) =>
                    nextChecked
                      ? [...current, book.id]
                      : current.filter((selectedId) => selectedId !== book.id),
                  );
                }}
              />
              <ItemMedia variant="image" className="h-14 w-10 rounded-sm shadow-sm">
                <span
                  aria-hidden="true"
                  className={`flex size-full items-end border-s-4 border-border p-1 text-metadata font-semibold ${book.cover}`}
                >
                  {book.monogram}
                </span>
              </ItemMedia>
              <ItemContent>
                <ItemTitle>
                  <FieldLabel htmlFor={checkboxId} className="cursor-pointer">
                    {book.title}
                  </FieldLabel>
                </ItemTitle>
                <ItemDescription>
                  {book.author} · {book.year}
                </ItemDescription>
              </ItemContent>
              <ItemActions>
                <Badge variant={book.badgeVariant}>{book.status}</Badge>
              </ItemActions>
            </Item>
          );
        })}
      </ItemGroup>
    </section>
  );
};

export default ItemBookLibrary;

